const cfg = $('Config (env)').item.json;
const sinceIso = cfg.since_iso;

const commitsRaw = $('GitHub: commits last 7d').all().map(i => i.json).flat();
const issuesRaw = $('GitHub: closed issues last 7d').all().map(i => i.json).flat();
const prsRaw = $('GitHub: recent PRs (filter merged)').all().map(i => i.json).flat();

const since = new Date(sinceIso);

// Filter PRs to those MERGED in the last 7d (the API returns recently updated; we tighten).
// Issues from the issues endpoint also include PRs — drop those (pull_request key present).
const issues = issuesRaw
  .filter(i => !i.pull_request)
  .filter(i => i.closed_at && new Date(i.closed_at) >= since);

const mergedPrs = prsRaw
  .filter(p => p.merged_at)
  .filter(p => new Date(p.merged_at) >= since);

const commits = commitsRaw
  .filter(c => c.commit && c.commit.author && c.commit.author.date)
  .filter(c => new Date(c.commit.author.date) >= since)
  // Deduplicate merge commits — they double-count work that's also in PRs.
  .filter(c => !(c.parents && c.parents.length > 1));

const pickCommit = c => ({
  sha: c.sha.slice(0, 7),
  url: c.html_url,
  message: (c.commit.message || '').split('\n')[0],
  author: (c.author && c.author.login) || c.commit.author.name
});
const pickIssue = i => ({
  number: i.number,
  url: i.html_url,
  title: i.title,
  closer: i.closed_by ? i.closed_by.login : null
});
const pickPr = p => ({
  number: p.number,
  url: p.html_url,
  title: p.title,
  author: p.user && p.user.login,
  additions: p.additions,
  deletions: p.deletions
});

return [{
  json: {
    repo: cfg.repo,
    language: cfg.language,
    destination: cfg.destination,
    discord_webhook_url: cfg.discord_webhook_url,
    slack_webhook_url: cfg.slack_webhook_url,
    since_iso: cfg.since_iso,
    until_iso: cfg.until_iso,
    counts: {
      commits: commits.length,
      merged_prs: mergedPrs.length,
      closed_issues: issues.length
    },
    commits: commits.map(pickCommit),
    merged_prs: mergedPrs.map(pickPr),
    closed_issues: issues.map(pickIssue)
  }
}];

