const claudeResponse = $json;
const aggregated = $('Aggregate week').item.json;
const contentParts = (claudeResponse.content || []).filter(p => p.type === 'text');
const markdown = contentParts.map(p => p.text).join('\n').trim();

const header = aggregated.language === 'fr'
  ? `**Résumé hebdomadaire — ${aggregated.repo}**\n_Semaine du ${aggregated.since_iso.slice(0,10)} au ${aggregated.until_iso.slice(0,10)}_\n\n`
  : `**Weekly summary — ${aggregated.repo}**\n_Week of ${aggregated.since_iso.slice(0,10)} to ${aggregated.until_iso.slice(0,10)}_\n\n`;

const body = header + markdown;

return [{ json: {
  destination: aggregated.destination,
  discord_webhook_url: aggregated.discord_webhook_url,
  slack_webhook_url: aggregated.slack_webhook_url,
  body,
  // Discord allows 2000 chars; chunk if needed.
  body_truncated: body.length > 1900 ? body.slice(0, 1900) + '\n_(truncated)_' : body
}}];
